# Note 'name' should not be shared by any two tests in this file
function run_test(test_input, expected, rtol, atol, upar_rtol=nothing; args...)
    # by passing keyword arguments to run_test, args becomes a Dict which can be used to
    # update the default inputs

    # Make a copy to make sure nothing modifies the input Dicts defined in this test
    # script.
    input = deepcopy(test_input)

    if upar_rtol === nothing
        upar_rtol = rtol
    end

    # Convert keyword arguments to a unique name
    name = input["output"]["run_name"]
    if length(args) > 0
        name = string(name, "_", (string(k, "-", v, "_") for (k, v) in args)...)

        # Remove trailing "_"
        name = chop(name)
    end

    # Provide some progress info
    println("    - testing ", name)

    # Update default inputs with values to be changed
    merge_dict_with_kwargs!(input; args...)
    input["output"]["run_name"] = name

    # Suppress console output while running
    quietoutput() do
        # run simulation
        run_moment_kinetics(input)
    end

    phi = nothing
    n_ion = nothing
    upar_ion = nothing
    ppar_ion = nothing
    f_ion = nothing
    n_neutral = nothing
    upar_neutral = nothing
    ppar_neutral = nothing
    f_neutral = nothing
    z, z_spectral = nothing, nothing
    vpa, vpa_spectral = nothing, nothing

    if global_rank[] == 0
        quietoutput() do

            # Load and analyse output
            #########################

            path = joinpath(realpath(input["output"]["base_directory"]), name)

            # open the output file(s)
            run_info = get_run_info_no_setup(path; dfns=true)

            # load species, time coordinate data
            n_ion_species = run_info.composition.n_ion_species
            n_neutral_species = run_info.composition.n_neutral_species
            ntime = run_info.nt
            time = run_info.time
            
            # load fields data
            phi_zrt = get_variable(run_info, "phi")
            Er_zrt = get_variable(run_info, "Er")
            Ez_zrt = get_variable(run_info, "Ez")

            # load velocity moments data
            n_ion_zrst = get_variable(run_info, "density")
            upar_ion_zrst = get_variable(run_info, "parallel_flow")
            ppar_ion_zrst = get_variable(run_info, "parallel_pressure")
            qpar_ion_zrst = get_variable(run_info, "parallel_heat_flux")
            v_t_ion_zrst = get_variable(run_info, "thermal_speed")
            n_neutral_zrst = get_variable(run_info, "density_neutral")
            upar_neutral_zrst = get_variable(run_info, "uz_neutral")
            ppar_neutral_zrst = get_variable(run_info, "pz_neutral")
            qpar_neutral_zrst = get_variable(run_info, "qz_neutral")
            v_t_neutral_zrst = get_variable(run_info, "thermal_speed_neutral")
            z = run_info.z
            z_spectral = run_info.z_spectral

