function runtests()
    # Create a temporary directory for test output
    test_output_directory = get_MPI_tempdir()

    @testset "numerical dissipation $vdiscretization" verbose=use_verbose for vdiscretization ∈ ("gausslegendre_pseudospectral", "chebyshev_pseudospectral")
        println("numerical dissipation tests $vdiscretization")

        @testset "base" begin
            this_test_input = deepcopy(test_input)
            this_test_input["output"]["base_directory"] = test_output_directory
            this_test_input["output"]["run_name"] *= "_$vdiscretization"
            this_test_input["vpa"]["discretization"] = vdiscretization
            this_test_input["vz"]["discretization"] = vdiscretization
            run_test(this_test_input, expected_base[vdiscretization], 1.e-10, 1.0e-14)
        end
        @testset "split 1" begin
            this_test_input = deepcopy(test_input_split_1_moment)
            this_test_input["output"]["base_directory"] = test_output_directory
            this_test_input["output"]["run_name"] *= "_$vdiscretization"
            this_test_input["vpa"]["discretization"] = vdiscretization
            this_test_input["vz"]["discretization"] = vdiscretization
            run_test(this_test_input, expected_split_1[vdiscretization], 1.e-10, 1.0e-14)
        end
        @testset "split 2" begin
            this_test_input = deepcopy(test_input_split_2_moments)
            this_test_input["output"]["base_directory"] = test_output_directory
            this_test_input["output"]["run_name"] *= "_$vdiscretization"
            this_test_input["vpa"]["discretization"] = vdiscretization
            this_test_input["vz"]["discretization"] = vdiscretization
            run_test(this_test_input, expected_split_2[vdiscretization], 1.e-10, 1.0e-14)
        end
        @testset "split 3" begin
            this_test_input = deepcopy(test_input_split_3_moments)
            this_test_input["output"]["base_directory"] = test_output_directory
            this_test_input["output"]["run_name"] *= "_$vdiscretization"
            this_test_input["vpa"]["discretization"] = vdiscretization
            this_test_input["vz"]["discretization"] = vdiscretization
            run_test(this_test_input, expected_split_3[vdiscretization], 1.e-10, 1.0e-14)
        end
    end

    if global_rank[] == 0
        # Delete output directory to avoid using too much disk space
        rm(realpath(test_output_directory); recursive=true)
    end
end

end # NumericalDissipationTests


